// Substitua 'meu_csv' pelo nome do campo que contém o texto do ficheiro CSV vindo do nó anterior
const csvText = $input.first().json.investimentos; 

// Separa o texto em linhas e remove linhas vazias
const lines = csvText.split('\n').filter(line => line.trim() !== '');

// Extrai o cabeçalho (primeira linha) e separa pelas vírgulas
const headers = lines[0].split(',').map(header => header.trim());

const result = [];

// Itera sobre as restantes linhas de dados
for (let i = 1; i < lines.length; i++) {
    const currentLine = lines[i].split(',');
    const obj = {};

    // Mapeia cada valor para o seu respetivo cabeçalho
    for (let j = 0; j < headers.length; j++) {
        obj[headers[j]] = currentLine[j] ? currentLine[j].trim() : '';
    }

    // O n8n exige que a saída de dados esteja encapsulada na propriedade 'json'
    result.push({ json: obj });
}

return result;

const result = [];

// Itera sobre todos os clientes que chegaram neste nó
for (const item of $input.all()) {
  const cliente = item.json;
  let mensagem_estatica = "";

  // Cria a mensagem estática baseada nas regras do MVP
  if (cliente.perfil === "Conservador") {
    mensagem_estatica = `Olá, ${cliente.nome}! Notamos que seu perfil é Conservador. Para o seu saldo atual, nossa recomendação tem foco em renda fixa e segurança. Sugestão de investimento: ${$input.first().json.produto}.`;

  } else if (cliente.perfil === "Moderado") {
    mensagem_estatica = `Olá, ${cliente.nome}! Sendo o seu perfil Moderado, o ideal para o seu saldo é buscar um mix equilibrado entre renda fixa e variável. Sugestão de investimento: ${$input.first().json.produto}.`;

  } else if (cliente.perfil === "Arrojado") {
    mensagem_estatica = `Olá, ${cliente.nome}! Identificamos seu perfil Arrojado. Para potencializar seu saldo, recomendamos dar ênfase em ações buscando maior potencial de retorno. Sugestão de investimento: ${$input.first().json.produto}.`;
  }

  // Adiciona a mensagem gerada ao pacote de dados do cliente
  result.push({
    json: {
      ...cliente,
      mensagem_final: mensagem_estatica
    }
  });
}

return result;

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const clientesVistos = new Set();
const out = [];

for (const item of $input.all()) {
  const c = item.json;
  // Utiliza o e-mail (ou o nome) como chave única do cliente
  const identificador = c.email || c.nome;

  // Se o cliente ainda não foi adicionado, processa apenas a primeira ocorrência
  if (!clientesVistos.has(identificador)) {
    clientesVistos.add(identificador);

    const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

    out.push({
      json: {
        ...c,
        email: String(c.email || "").trim(),
        saldo_numerico: saldoNum
      }
    });
  }
}

return out;

// Resgata os dados originais dos clientes diretamente do nó antes da IA
const clientes = $('Code in JavaScript').all();

return $input.all().map((item, index) => {
  const j = item.json;

  // Recupera os dados do cliente usando a sua posição na fila
  const c = clientes[index] ? clientes[index].json : {};

  // O nó da IA (Message a model) geralmente retorna a resposta na variável "text"
  let respostaIA = j.text || j.message?.content || j.output || j.response || j.content || "";

  let subject = "Sugestão de Investimento";
  let text_body = "";
  let html_body = "";

  // CENÁRIO 1: A IA retornou um objeto pronto (o n8n já fez o parse automático)
  if (typeof respostaIA === 'object' && respostaIA !== null) {
      subject = respostaIA.subject || subject;
      text_body = respostaIA.text_body || "";
      html_body = respostaIA.html_body || "";
  } 
  // CENÁRIO 2: A IA retornou texto (String) com ou sem marcações markdown
  else {
      let textoIA = String(respostaIA);

      try {
        // Limpeza cirúrgica: pega exatamente da primeira '{' até a última '}'
        const inicio = textoIA.indexOf('{');
        const fim = textoIA.lastIndexOf('}');

        if (inicio !== -1 && fim !== -1) {
          const jsonLimpo = textoIA.substring(inicio, fim + 1);
          const parsed = JSON.parse(jsonLimpo);

          subject = parsed.subject || subject;
          text_body = parsed.text_body || "";
          html_body = parsed.html_body || "";
        }
      } catch (erro) {
        // Prevenção de erro extremo: Extrai usando RegEx se o JSON estiver quebrado
        const extrairCampo = (chave) => {
            const regex = new RegExp(`"${chave}"\\s*:\\s*"(.*?)"(?:\\s*,|\\s*\\})`, "s");
            const match = textoIA.match(regex);
            return match ? match[1] : "";
        };

        subject = extrairCampo("subject") || subject;
        text_body = extrairCampo("text_body") || textoIA;
        html_body = extrairCampo("html_body") || `<p>${textoIA}</p>`;
      }
  }

  // Define as variáveis finais para a tabela
  return {
    json: {
      ok: true,
      to: c.email || "empty", // Puxa o email do cliente resgatado
      subject: subject,
      text_body: text_body,
      html_body: html_body,   // Recebe o conteúdo HTML perfeitamente

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: c.nome,
        perfil: c.perfil,
        produto: c.produto, 
        minimo: c.minimo,
        rentabilidade: c.rentabilidade,
        motivo: c.mensagem_final
      }
    }
  };
});
